SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"cancer_type\", \"treatment_regimen\", \"control_regimen\", \"type_of_combination\", \"class_of_ici\", \"name_of_ici\", \"type_of_therapy\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 2' AND \"cancer_type\" = 'Non-Small Cell Lung' AND \"class_of_ici\" = 'CTLA4' AND \"type_of_therapy\" = 'combination' AND \"type_of_combination\" ILIKE '%CTLA-4%';